import {trainingBag} from './bag.js';
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export const FLIGHT_PIXEL=2.3,APEX_FLIGHT_PIXEL=FLIGHT_PIXEL*3;
export const SHOT_FIELDS={carry:[50,330],roll:[0,40],sdSide:[0,50],sdLong:[0,40],start:[-10,10],curve:[-50,50],bias:[-35,35],height:[5,50],bigPct:[0,25],bigShift:[0,100],bigShort:[0,60],rho:[-.8,.8]};
export function defaultMemberBag(base){return trainingBag({...base,shotType:'tee',customBag:null}).map(c=>({...c,start:0,curve:0,bias:0,height:c.stock>200?32:25,bigPct:0,bigDirection:'both',bigShift:c.stock>200?40:22,bigShort:12,rho:0}));}
export function cleanMemberBag(saved,base){const defaults=defaultMemberBag(base);return defaults.map(d=>{const old=Array.isArray(saved)?saved.find(c=>c.club===d.club):null;if(!old)return d;const out={...d};for(const [key,[lo,hi]]of Object.entries(SHOT_FIELDS)){const v=key==='carry'?Number(old.stock)-Number(old.roll):Number(old[key]);out[key]=Number.isFinite(v)?clamp(v,lo,hi):(key==='carry'?d.stock-d.roll:d[key]);}out.stock=out.carry+out.roll;delete out.carry;out.bigDirection=['left','right','both'].includes(old.bigDirection)?old.bigDirection:'both';return out;});}
export function editingPattern(club){return{...club,carry:club.stock-club.roll};}
export const APEX_BASE_Y=250,APEX_HEIGHT_PIXEL=3,FINISH_Y=280,APEX_X=393.75,FINISH_X=400;
export const apexY=p=>APEX_BASE_Y-p.height*APEX_HEIGHT_PIXEL;
export function flightHandles(p){const start=p.carry*Math.tan(p.start*Math.PI/180),curve=p.curve+(p.bias||0);return{mid:.5*start+.25*curve,end:start+curve};}
export function moveFlightHandle(p,handle,lateral){
 const q=flightHandles(p),bias=p.bias||0;
 // Apex edits preserve the endpoint. Finish edits preserve the chosen start line.
 if(handle==='end'){const start=p.carry*Math.tan(p.start*Math.PI/180);return{...p,curve:clamp(lateral-start-bias,-50,50)};}
 const start=clamp(Math.atan2(4*lateral-q.end,p.carry)*180/Math.PI,-10,10),s=p.carry*Math.tan(start*Math.PI/180);
 return{...p,start,curve:clamp(q.end-s-bias,-50,50)};
}
export function moveApex(p,lateral,y){return{...moveFlightHandle(p,'mid',lateral),height:clamp((APEX_BASE_Y-y)/APEX_HEIGHT_PIXEL,5,50)};}
export function applyFlightToBag(bag,sourceClub,p){const carry=p.carry;return bag.map(c=>{if(c.club===sourceClub)return{...p,club:c.club,stock:p.carry+p.roll,carry:undefined};const ratio=(c.stock-c.roll)/carry;return{...c,start:p.start,curve:clamp(p.curve*ratio,-50,50),bias:clamp((p.bias||0)*ratio,-35,35),height:clamp(p.height*Math.sqrt(ratio),5,50)};});}
export function resetFlight(bag,club=null){return bag.map(c=>!club||c.club===club?{...c,start:0,curve:0,bias:0,height:c.stock>200?32:25}:c);}
export function validPlayerProfile(p){
 if(!p||!['0','5','10','20'].includes(p.handicap)||!Number.isFinite(p.limit)||p.limit<180||p.limit>330||p.shotMode&&!['basic','custom'].includes(p.shotMode))return false;
 if(p.shotMode!=='custom')return true;
 const names=['Driver','3 wood','Hybrid','5 iron','6 iron','7 iron','8 iron','9 iron','PW','SW'];
 return Array.isArray(p.bag)&&p.bag.length===10&&new Set(p.bag.map(c=>c.club)).size===10&&p.bag.every(c=>names.includes(c.club)&&['both','left','right'].includes(c.bigDirection)&&Object.entries(SHOT_FIELDS).every(([k,[lo,hi]])=>{const v=k==='carry'?c.stock-c.roll:c[k];return Number.isFinite(v)&&v>=lo&&v<=hi;}));
}
export function flightDescription(p){const h=flightHandles(p),curve=p.curve+(p.bias||0);return`${Math.abs(p.start)<.15?'Starts on target':p.start>0?'Starts right':'Starts left'} · ${Math.abs(curve)<.5?'flies straight':curve<0?'bends left':'bends right'} · ${Math.abs(h.end)<.5?'finishes on target':'finishes '+Math.round(Math.abs(h.end))+' yd '+(h.end<0?'left':'right')}`;}
export function flightSVG(p){
 const h=flightHandles(p),peak=apexY(p),point=t=>{const x=300+100*(1-(1-t)**4)+FLIGHT_PIXEL*(1+2*Math.sin(Math.PI*t))*(p.carry*Math.tan(p.start*Math.PI/180)*t+(p.curve+(p.bias||0))*t*t),y=t<=.5?peak+(420-peak)*(1-2*t)**2:peak+(FINISH_Y-peak)*(2*t-1)**2;return{x,y};},path=Array.from({length:81},(_,i)=>{const q=point(i/80);return`${i?'L':'M'}${q.x.toFixed(2)},${q.y.toFixed(2)}`;}).join(' ');
 return`<defs><linearGradient id="editorGrass" x2="0" y2="1"><stop stop-color="#d4e6c4"/><stop offset="1" stop-color="#f1f5e9"/></linearGradient></defs><rect width="800" height="480" rx="12" fill="url(#editorGrass)"/><path d="M0 285Q240 220 400 243T800 285V480H0Z" fill="#bcd6a2" opacity=".45"/><ellipse cx="400" cy="280" rx="76" ry="28" fill="#a3c77e"/><path d="M300 420L400 280" stroke="#748567" stroke-width="1.5" stroke-dasharray="5 7"/><circle cx="400" cy="280" r="9" fill="none" stroke="#587147" stroke-width="2"/><path d="M400 280v-42l20 7-20 8" fill="#e9eddd" stroke="#526344" stroke-width="2"/><text x="485" y="264" text-anchor="start" fill="#526344" font-size="14">TARGET</text><g id="addressGolfer" aria-label="Golfer at address"><ellipse cx="228" cy="455" rx="48" ry="6" fill="#37543b22"/><circle cx="225" cy="367" r="11" fill="#31533d"/><path d="M236 382l-9 30-15 31m16-31 24 29M235 385l23 13 14 4" fill="none" stroke="#31533d" stroke-width="11" stroke-linecap="round"/><path d="M230 377l12 14 22 13" fill="none" stroke="#43634a" stroke-width="10" stroke-linecap="round"/><path d="M270 402l31 18" stroke="#6a715f" stroke-width="3"/><path d="M207 446h14m29 0h17" stroke="#294737" stroke-width="6" stroke-linecap="round"/><path d="M294 421h11" stroke="#485445" stroke-width="4"/></g><path id="personalFlightTracer" d="${path}" fill="none" stroke="#d74d44" stroke-width="5" stroke-linecap="round"/><circle cx="300" cy="420" r="6" fill="#fffef8" stroke="#6d8161"/><g data-handle="mid" tabindex="0" role="button" aria-label="Flight apex, ${Math.round(p.height)} yards illustrative height. Arrow keys change direction and height."><circle cx="${APEX_X+APEX_FLIGHT_PIXEL*h.mid}" cy="${peak}" r="23" fill="#df7661" stroke="#fffdf5" stroke-width="3"/><path d="M${APEX_X-11+APEX_FLIGHT_PIXEL*h.mid} ${peak}h22M${APEX_X+APEX_FLIGHT_PIXEL*h.mid} ${peak-11}v22" stroke="white" stroke-width="2"/></g><text x="${clamp(APEX_X+APEX_FLIGHT_PIXEL*h.mid,60,740)}" y="${peak-34}" text-anchor="middle" fill="#42583e" font-size="15">Drag apex ↔ ↕</text><g data-handle="end" tabindex="0" role="button" aria-label="Flight finish. Left and right arrows move the finish."><circle cx="${FINISH_X+FLIGHT_PIXEL*h.end}" cy="280" r="23" fill="#397b9f" stroke="#fffdf5" stroke-width="3"/><path d="M${FINISH_X-11+FLIGHT_PIXEL*h.end} 280h22m-18-4-4 4 4 4m14-8 4 4-4 4" fill="none" stroke="white" stroke-width="2"/></g><text x="${clamp(FINISH_X+FLIGHT_PIXEL*h.end,60,740)}" y="323" text-anchor="middle" fill="#42583e" font-size="15">Drag finish ↔</text>`;
}
export function heightSVG(p){const y=166-p.height*2.4;return`<rect width="600" height="210" rx="12" fill="#edf3e8"/><path d="M40 166H560" stroke="#8da080"/><path d="M40 166Q300 ${166-p.height*4.8} 560 166" fill="none" stroke="#2c6546" stroke-width="4"/><g data-handle="height"><circle cx="300" cy="${y}" r="20" fill="#e9b858" stroke="#fffdf5" stroke-width="3"/><path d="M300 ${y-10}v20m-4-16 4-4 4 4m-8 12 4 4 4-4" fill="none" stroke="#624f2c" stroke-width="2"/></g><text x="560" y="24" text-anchor="end" fill="#526344" font-size="12">PEAK · ${Math.round(p.height)} YD</text><circle cx="40" cy="166" r="5" fill="#fffef8" stroke="#7a8e6c"/><text x="40" y="192" fill="#748366" font-size="11">SIDE VIEW · DRAG UP / DOWN</text><text x="560" y="192" text-anchor="end" fill="#748366" font-size="11">HEIGHT IS VISUAL ONLY</text>`;}
